<script lang="ts">
  import { onMount } from 'svelte';
  let { alert, clip, loading = false, error = '', onClose, formatDate, duration, labelClass, statusLabel } = $props<any>();
  let dialog: HTMLDivElement;
  function isHybridAlert() { return Math.abs(Number(alert.threshold) - 0.85) < 0.001; }
  function finishLabel() { return String(alert.status ?? '').toLowerCase() === 'interrupted' ? 'Fin' : 'Fin (liberación VadCLIP)'; }
  function handleKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape') { event.preventDefault(); onClose(); return; }
    if (event.key !== 'Tab') return;
    const items = [...dialog.querySelectorAll<HTMLElement>('button:not([disabled]), video, [href], input:not([disabled]), [tabindex]:not([tabindex="-1"])')];
    const first = items[0], last = items.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
  }
  onMount(() => dialog.querySelector<HTMLElement>('[data-initial-focus]')?.focus());
</script>

<div class="modal-overlay" role="presentation" onclick={(event) => { if (event.target === event.currentTarget) onClose(); }}>
  <div class="dialog" bind:this={dialog} role="dialog" tabindex="-1" aria-modal="true" aria-labelledby="event-detail-title" onkeydown={handleKeydown}><div class="dialog-top"><div><div class="eyebrow">EVIDENCIA DEL EVENTO</div><h2 id="event-detail-title">{labelClass(alert.clase)}</h2><p>{alert.camera ?? 'Cámara no identificada'} · {formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</p></div><button class="close" data-initial-focus type="button" aria-label="Cerrar detalle del evento" onclick={onClose}>×</button></div><div class="clip-panel" aria-live="polite">{#if loading}<div>Consultando evidencia…</div>{:else if clip?.status === 'recording'}<div>● Grabando…<small>El clip se actualizará automáticamente.</small></div>{:else if clip?.status === 'partial'}<div class="partial-clip"><strong>Clip parcial</strong><span>La evidencia terminó antes de completar toda la grabación.</span>{#if clip?.url}<video controls preload="metadata" src={clip.url}><track kind="captions" /></video>{/if}</div>{:else if clip?.url}<video controls preload="metadata" src={clip.url}><track kind="captions" /></video>{:else}<div>{statusLabel(clip?.status)}: no hay un clip disponible todavía.</div>{/if}</div>{#if error}<p class="error">No se pudo consultar el clip: {error}</p>{/if}<dl><div><dt>ID del evento</dt><dd>{alert.id ?? '—'}</dd></div><div><dt>Cámara</dt><dd>{alert.camera ?? '—'}</dd></div>{#if alert.session_id}<div><dt>Sesión</dt><dd>{alert.session_id}</dd></div>{/if}<div><dt>Inicio</dt><dd>{formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</dd></div><div><dt>{finishLabel()}</dt><dd>{formatDate(alert.timestamp_fin ?? alert.fecha_hora_fin)}</dd></div><div><dt>Duración</dt><dd>{duration(alert.duracion_segundos ?? clip?.duration_seconds)}</dd></div><div><dt>Estado</dt><dd>{statusLabel(alert.status)}</dd></div><div><dt>{isHybridAlert() ? 'Anomalía VadCLIP' : 'Confianza'}</dt><dd>{alert.confianza == null ? '—' : `${(Number(alert.confianza) * 100).toFixed(1)}%`}</dd></div><div><dt>{isHybridAlert() ? 'Umbral de apertura' : 'Umbral'}</dt><dd>{alert.threshold == null ? '—' : `${(Number(alert.threshold) * 100).toFixed(1)}%`}</dd></div>{#if alert.interruption_reason}<div><dt>Motivo de interrupción</dt><dd>{alert.interruption_reason}</dd></div>{/if}</dl></div>
</div>

<style>.modal-overlay{position:fixed;inset:0;background:#0b1c32a8;display:flex;justify-content:center;align-items:center;padding:18px;z-index:50}.dialog{background:#fff;width:100%;max-width:690px;border-radius:12px;padding:28px;max-height:95vh;overflow:auto}.dialog-top{display:flex;justify-content:space-between;gap:15px}.dialog h2{margin:8px 0;font-size:24px}.dialog p{color:#4a6178;font-size:12px}.close{border:0;background:none;font-size:28px}.clip-panel{background:#071a32;color:#dceafb;border-radius:8px;min-height:220px;display:grid;place-items:center;overflow:hidden;padding:20px;text-align:center}.clip-panel small{display:block;margin-top:8px;color:#a9c9e5;font-size:11px}.clip-panel video{width:100%;max-height:390px;margin-top:12px}.partial-clip{display:grid;gap:7px;place-items:center}.partial-clip strong{color:#ffd49b}.partial-clip span{font-size:12px}.error{color:#a3494d}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:17px}dt{font-size:10px;color:#71879d;text-transform:uppercase}dd{margin:4px 0;font-size:13px}.eyebrow{color:#6991ae;font-size:10px;font-weight:800;letter-spacing:1.5px}</style>
